class Solution {
public:
    int numTimesAllBlue(vector<int>& flips) {
        int maxPos = 0;
        int count = 0;
        for (int i = 0; i < (int)flips.size(); i++) {
            if (flips[i] > maxPos) maxPos = flips[i];
            if (maxPos == i + 1) count++;
        }
        return count;
    }
};
